const ufaClock=()=>Object.fromEntries(ufaFormatter.formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,+p.value]));
const ufaDay=c=>new Date(Date.UTC(c.year,c.month-1,c.day)).getUTCDay();
const THEMES=[['graphite','◐','#171a1f']];
const currentWeek=()=>{const c=ufaClock();return Math.max(1,Math.min(MAX_WEEK,Math.floor((Date.UTC(c.year,c.month-1,c.day)-BASE_UTC)/604800000)+1))};
const today=()=>ufaDay(ufaClock())||7;
const dateOf=(week,day)=>new Date(BASE_UTC+((week-1)*7+day-1)*86400000);
const toMinutes=time=>+time.slice(0,2)*60+ +time.slice(3,5);
