 const detail=$('offlineModalState');if(detail)detail.textContent=t(offlineMode==='file'?'offlineFileHint':offlineMode==='ready'?'offlineReadyHint':offlineMode==='loading'?'offlineLoadingHint':'offlineUnavailable');
