async function setupOffline(){
 if(location.protocol==='file:'){offlineMode='file';refreshOfflineHint();return}
 if(!window.isSecureContext||!('serviceWorker' in navigator)){offlineMode='unavailable';refreshOfflineHint();return}
 try{
  const registration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});
  await new Promise((resolve,reject)=>{
   if(registration.active){resolve();return}
   const worker=registration.installing||registration.waiting;if(!worker){reject(new Error('No worker'));return}
   const timeout=setTimeout(()=>reject(new Error('Offline timeout')),15000);
   const changed=()=>{if(worker.state==='activated'){clearTimeout(timeout);worker.removeEventListener('statechange',changed);resolve()}else if(worker.state==='redundant'){clearTimeout(timeout);worker.removeEventListener('statechange',changed);reject(new Error('Offline installation failed'))}};
   worker.addEventListener('statechange',changed);changed();
  });
  offlineMode='ready';notifyScheduleChanges(initialChanges);
 }catch{offlineMode='unavailable'}
 refreshOfflineHint();
}
