  lines.push(t('pair',{n:row[1]})+' · '+row[9]+'–'+row[10],t('subject')+': '+subject(row),t('room')+': '+(room(row[4])||'—'),t('teacher')+': '+(teacher(row)||t('noTeacher')),t('weeks')+': '+formatWeek(row));
